WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') search_key,%s::integer uid,%s::integer lim), s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' all_branch FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.id_oi,a.station_code,a.production_order,a.step_code,a.machine_code,a.mes_scheduling_code,a.quantity,a.staff_code,a.date0,a.time0,a.start_yn,a.quantity_product,a.cavity,a.product_code,count(*) OVER() total FROM public.mes_oi_bo_shot a CROSS JOIN s WHERE s.ok IS NOT NULL AND a.date0 BETWEEN s.d1 AND s.d2 AND (s.search_key='' OR a.id_oi ILIKE '%%'||s.search_key||'%%' OR a.product_code=ANY(string_to_array(s.search_key,',')) OR a.machine_code=ANY(string_to_array(s.search_key,','))) AND (s.all_branch OR EXISTS(SELECT 1 FROM public.mes_oi_confirm c WHERE c.id_oi=a.id_oi AND c.branch_code=ANY(string_to_array(s.bs,',')))) ORDER BY a.date0 DESC,a.time0 DESC,a.id_oi LIMIT (SELECT lim FROM p);
